void selection_sort(int a[], int n)
{
    int i, min, temp, unused;
    i = 0;
    min = 0;
    unused = 0;
    while(i < n)
    {
        if(a[i] < a[min])
        {
            min = i;
        }
        i = i + 1;
    }
    if(min != 0)
    {
        temp = a[0];
        a[0] = a[min];
        a[min] = temp;
    }
}
